import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.BYYsWsaA.js";const p=JSON.parse('{"title":"后端健康分析 V2 设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"backend-health-analysis-v2.md","filePath":"backend-health-analysis-v2.md","lastUpdated":1773595350000}'),d={name:"backend-health-analysis-v2.md"};function r(c,l,t,n,s,h){return a(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="后端健康分析-v2-设计说明" tabindex="-1">后端健康分析 V2 设计说明 <a class="header-anchor" href="#后端健康分析-v2-设计说明" aria-label="Permalink to &quot;后端健康分析 V2 设计说明&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在不引入 <code>PySpark</code> 等重型数据框架的前提下，将一期后端分析从“单次测量规则判断”升级为“单次规则 + 时间窗统计 + 个人基线偏移”的轻量分析方案。</p><p>该方案适合当前毕设阶段：</p><ul><li>数据量较小，主要需求是在线 API 分析</li><li>需要结果可解释，便于答辩展示</li><li>需要在现有 Django 服务中快速落地</li></ul><h2 id="为什么不使用-pyspark" tabindex="-1">为什么不使用 PySpark <a class="header-anchor" href="#为什么不使用-pyspark" aria-label="Permalink to &quot;为什么不使用 PySpark&quot;">​</a></h2><p>当前系统的核心是：</p><ul><li>智能戒指上报数据接入</li><li>单次测量解析</li><li>风险评分</li><li>历史查询与告警</li></ul><p>这属于在线业务链路，不属于超大规模离线批处理场景。<code>PySpark</code> 更适合：</p><ul><li>海量历史数据离线聚合</li><li>批量特征工程</li><li>分布式训练或批量统计</li></ul><p>当前阶段如果直接引入 <code>PySpark</code>，会明显增加部署和调试复杂度，但对实时 API 价值不大。</p><h2 id="当前实现结构" tabindex="-1">当前实现结构 <a class="header-anchor" href="#当前实现结构" aria-label="Permalink to &quot;当前实现结构&quot;">​</a></h2><p>核心文件：</p><ul><li><code>backend/monitoring/services.py</code></li></ul><p>分析入口：</p><ul><li><code>analyze_measurement(measurement)</code></li></ul><p>算法版本：</p><ul><li><code>rules-window-baseline-v2</code></li></ul><h2 id="分析结构" tabindex="-1">分析结构 <a class="header-anchor" href="#分析结构" aria-label="Permalink to &quot;分析结构&quot;">​</a></h2><h3 id="_1-实时规则层" tabindex="-1">1. 实时规则层 <a class="header-anchor" href="#_1-实时规则层" aria-label="Permalink to &quot;1. 实时规则层&quot;">​</a></h3><p>基于当前一次测量直接判断：</p><ul><li>心率过快</li><li>心率过慢</li><li>HRV 异常偏高</li><li>压力过高</li><li>血氧偏低</li><li>体温偏高</li></ul><p>如果同时出现“心动过速 + HRV 不稳定 + 低血氧”，会标记为更高风险的聚类异常。</p><h3 id="_2-时间窗统计层" tabindex="-1">2. 时间窗统计层 <a class="header-anchor" href="#_2-时间窗统计层" aria-label="Permalink to &quot;2. 时间窗统计层&quot;">​</a></h3><p>在最近 <code>30 分钟</code> 和 <code>24 小时</code> 范围内，统计重复异常：</p><ul><li><code>window_repeated_tachycardia_30m</code></li><li><code>window_repeated_low_oxygen_30m</code></li><li><code>window_repeated_hrv_instability_30m</code></li><li><code>window_repeated_high_risk_24h</code></li></ul><p>作用：</p><ul><li>避免只看单条测量造成偶然误报</li><li>能体现“持续异常”而不是“瞬时异常”</li></ul><h3 id="_3-个人基线层" tabindex="-1">3. 个人基线层 <a class="header-anchor" href="#_3-个人基线层" aria-label="Permalink to &quot;3. 个人基线层&quot;">​</a></h3><p>从最近 <code>7 天</code> 的历史测量中提取个人基线均值：</p><ul><li>心率基线</li><li>HRV 基线</li><li>血氧基线</li><li>体温基线</li></ul><p>然后比较当前值是否明显偏离个人历史水平：</p><ul><li><code>baseline_heart_rate_above_personal_baseline</code></li><li><code>baseline_oxygen_below_personal_baseline</code></li><li><code>baseline_hrv_above_personal_baseline</code></li><li><code>baseline_temperature_above_personal_baseline</code></li></ul><p>作用：</p><ul><li>不同用户共享固定阈值的问题会被缓解</li><li>更符合健康监测里“个体差异明显”的特点</li></ul><h3 id="_4-佩戴有效性修正" tabindex="-1">4. 佩戴有效性修正 <a class="header-anchor" href="#_4-佩戴有效性修正" aria-label="Permalink to &quot;4. 佩戴有效性修正&quot;">​</a></h3><p>如果当前佩戴状态不稳定，系统会降低最终风险分数，并补充：</p><ul><li><code>context_unstable_wear_state</code></li></ul><p>作用：</p><ul><li>避免在无效佩戴状态下过度解读测量结果</li></ul><h2 id="输出结构" tabindex="-1">输出结构 <a class="header-anchor" href="#输出结构" aria-label="Permalink to &quot;输出结构&quot;">​</a></h2><p>分析结果现在包含：</p><ul><li><code>algorithm_version</code></li><li><code>risk_level</code></li><li><code>risk_score</code></li><li><code>labels</code></li><li><code>triggers</code></li><li><code>details</code></li><li><code>summary</code></li><li><code>should_alert</code></li></ul><p>其中 <code>details</code> 是给前端、后续 AI 解读和论文展示使用的结构化信息，包含：</p><ul><li><code>realtime_flags</code></li><li><code>window_flags</code></li><li><code>baseline_flags</code></li><li><code>window_stats</code></li><li><code>baselines</code></li><li><code>wearing_effective</code></li></ul><h2 id="风险等级说明" tabindex="-1">风险等级说明 <a class="header-anchor" href="#风险等级说明" aria-label="Permalink to &quot;风险等级说明&quot;">​</a></h2><p>综合分数后映射为：</p><ul><li><code>low</code></li><li><code>moderate</code></li><li><code>high</code></li><li><code>critical</code></li></ul><p>当前仍然属于“异常心律风险预警/房颤风险筛查”逻辑，不应表述为临床确诊。</p><h2 id="后续可继续增强的方向" tabindex="-1">后续可继续增强的方向 <a class="header-anchor" href="#后续可继续增强的方向" aria-label="Permalink to &quot;后续可继续增强的方向&quot;">​</a></h2><h3 id="_1-更稳的基线建模" tabindex="-1">1. 更稳的基线建模 <a class="header-anchor" href="#_1-更稳的基线建模" aria-label="Permalink to &quot;1. 更稳的基线建模&quot;">​</a></h3><p>当前使用均值，后续可以换成：</p><ul><li>中位数</li><li>分位数</li><li>分时段基线（白天 / 夜间）</li></ul><h3 id="_2-更完整的时间序列特征" tabindex="-1">2. 更完整的时间序列特征 <a class="header-anchor" href="#_2-更完整的时间序列特征" aria-label="Permalink to &quot;2. 更完整的时间序列特征&quot;">​</a></h3><p>例如：</p><ul><li>最近 1 小时异常比例</li><li>夜间异常次数</li><li>过去 7 天风险趋势</li></ul><h3 id="_3-轻量机器学习" tabindex="-1">3. 轻量机器学习 <a class="header-anchor" href="#_3-轻量机器学习" aria-label="Permalink to &quot;3. 轻量机器学习&quot;">​</a></h3><p>在当前规则和统计特征基础上，后续可引入：</p><ul><li><code>scikit-learn</code></li><li><code>XGBoost</code></li><li><code>LightGBM</code></li></ul><p>作为离线训练、在线推理的下一阶段演进。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>当前 V2 方案相比原先的单次规则判断，已经具备：</p><ul><li>更强的可解释性</li><li>更合理的个体化判断</li><li>更稳定的连续异常识别能力</li></ul><p>它仍然是轻量级实现，但已经更适合作为毕设后端分析核心。</p>',64)])])}const _=e(d,[["render",r]]);export{p as __pageData,_ as default};
